(function(){var script=document.currentScript;var SITE=script.getAttribute("data-site")||location.hostname;var WORKER=script.getAttribute("data-worker")||(location.protocol+"//"+script.src.split("/")[2]);function send(path,extra){var payload=JSON.stringify(Object.assign({site:SITE,path:location.pathname,ts:Date.now()},extra));if(navigator.sendBeacon){navigator.sendBeacon(WORKER+path,new Blob([payload],{type:"text/plain"}))}else{fetch(WORKER+path,{method:"POST",body:payload,headers:{"Content-Type":"text/plain"},keepalive:!0}).catch(function(){})}}
send("/t",{referrer:document.referrer});function classifyLink(href){if(href.indexOf("wa.me/")!==-1||href.indexOf("whatsapp.com/send")!==-1)return"contact_whatsapp";if(href.indexOf("t.me/")!==-1)return"contact_telegram";if(href.indexOf("add-to-cart=")!==-1||href.indexOf("/checkout")!==-1||href.indexOf("/step/")!==-1)return"buy_checkout";if(href.indexOf("proef")!==-1||href.indexOf("trial")!==-1||href.indexOf("kokeilu")!==-1)return"trial_click";return null}
document.addEventListener("click",function(e){var el=e.target.closest("[data-track]");if(el){send("/e",{type:el.getAttribute("data-track"),label:(el.textContent||"").trim().slice(0,80)});return}
var a=e.target.closest("a[href]");var type=a&&classifyLink(a.href.toLowerCase());if(type)send("/e",{type:type,label:((a.textContent||"").trim()||a.href).slice(0,80),detail:{href:a.href.slice(0,300)}})});document.addEventListener("submit",function(e){var form=e.target;if(form.matches("[role=search], .search-form")||form.querySelector("input[type=search], input[name=s]"))return;send("/e",{type:form.getAttribute("data-track-form")||"form_submit",label:form.getAttribute("id")||form.getAttribute("name")||form.getAttribute("action")||""})})})()